<?php
$routes = [];
if (($_SERVER['REQUEST_METHOD'] ?? 'GET') === 'GET' && (isset($_GET['depart']) || isset($_GET['arrivee']))) {
    $routes = ClientApi::data($api->request('GET', 'api/itineraires?' . http_build_query(['depart' => trim((string)($_GET['depart'] ?? '')), 'arrivee' => trim((string)($_GET['arrivee'] ?? ''))])));
}
$routes = is_array($routes) ? $routes : [];
$transports = ClientApi::data($api->request('GET', 'api/transports'));
?>
<section class="panel"><h2>Rechercher un trajet</h2><form method="get" class="feature-search"><input type="hidden" name="page" value="transport"><label>Départ<input name="depart" value="<?= client_h($_GET['depart'] ?? '') ?>" maxlength="180" required></label><label>Arrivée<input name="arrivee" value="<?= client_h($_GET['arrivee'] ?? '') ?>" maxlength="180" required></label><button class="btn" type="submit">Rechercher</button></form></section>
<?php if (isset($_GET['depart']) || isset($_GET['arrivee'])): ?><section class="feature-grid"><?php foreach ($routes as $route): ?><article class="panel"><span class="eyebrow"><?= client_h($route['transport'] ?? '') ?> · <?= client_h($route['transporteur'] ?? '') ?></span><h2><?= client_h($route['depart_libelle'] ?? '') ?> → <?= client_h($route['arrivee_libelle'] ?? '') ?></h2><p><?= client_h($route['depart_at'] ?? 'Horaire à confirmer') ?> · <?= client_h($route['duree_minutes'] ?? '—') ?> min</p><p><strong><?= client_h($route['tarif'] ?? 'Tarif à confirmer') ?> <?= client_h($route['devise'] ?? '') ?></strong></p><?php if ($user): ?><form method="post" data-confirm="Confirmer la réservation ? Voulez-vous envoyer une demande pour ce trajet ?"><?= client_csrf_field() ?><input type="hidden" name="action" value="reserve"><input type="hidden" name="itineraire_id" value="<?= (int)$route['id'] ?>"><input type="hidden" name="quantite" value="1"><button class="btn" type="submit">Demander une réservation</button><small>La demande reste soumise à confirmation du transporteur.</small></form><?php else: ?><a class="btn" href="?page=login">Connectez-vous pour réserver</a><?php endif; ?></article><?php endforeach; ?></section><?php if (!$routes): ?><div class="panel empty"><p>Aucun itinéraire disponible pour cette recherche.</p></div><?php endif; ?><?php endif; ?>
<section class="panel"><h2>Modes de transport disponibles</h2><div class="feature-grid"><?php foreach (is_array($transports) ? $transports : [] as $transport): ?><article><h3><?= client_h($transport['nom'] ?? '') ?></h3><p><?= client_h($transport['description'] ?? '') ?></p></article><?php endforeach; ?></div></section>
